let firework = [];
let colors = ['#111d5e', '#c70039', '#f37121', '#c0e218'];
let g;
let curtime;

function setup() {
	createCanvas(windowWidth, windowHeight);
	curtime=millis();

}

function draw() {
	fill(0, 10);
	rect(0, 0, width, height);

	g = createVector(0, 0.01);
	if(millis() > curtime + 2000){
		createRocket(5,5);
		curtime = millis();
	}
	if(firework.length > 0) {
		for(let i = 0; i < firework.length; i++) {
			firework[i].show();
			firework[i].move();
			firework[i].applyForce(g);

			if(firework[i].vel.y > 0) firework[i].boom();
			if(firework[i].isDead()) firework.splice(i, 1);
		}
	}
}

