function createRocket(posX,posY) {
	for(let i = 0; i < 100; i++) {
		firework.push(new Ball(posX, posY, 5, colors[i%colors.length]));
	}
}

class Ball {
	constructor(x, y, s_, c_) {
		this.pos = createVector(x, y);
		this.vel = createVector(0, -1);
		this.acel = createVector(0, -1);
		this.s = s_;
		this.c = c_;
		this.aux = true;
		this.a = 255;
	}

	show() {
		noStroke();
		fill(this.c);
		ellipse(this.pos.x, this.pos.y, this.s, this.s);

		if(!this.aux) this.a -= random(2, 4);
	}

	move() {
		this.vel.add(this.acel);
		this.vel.limit(5);
		this.pos.add(this.vel);
		this.acel.mult(0);
	}

	applyForce(f) {
		this.acel.add(f);
	}

	boom() {
		if(this.aux) {
			this.acel = p5.Vector.random2D();
			this.acel.normalize();
			this.acel.mult(random(2));
			this.aux = false;
		}
	}

	isDead() {
		if(this.a < 10) return true;
		else return false;
	}
}

